import{_ as s,o as a,c as n,ai as e}from"./chunks/framework.Ba-VnP44.js";const b=JSON.parse('{"title":"IIoT 核心问题清单","description":"","frontmatter":{},"headers":[],"relativePath":"scenarios/enterprise-digital/iiot.md","filePath":"scenarios/enterprise-digital/iiot.md"}'),r={name:"scenarios/enterprise-digital/iiot.md"};function i(d,t,l,p,o,h){return a(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="iiot-核心问题清单" tabindex="-1">IIoT 核心问题清单 <a class="header-anchor" href="#iiot-核心问题清单" aria-label="Permalink to “IIoT 核心问题清单”">​</a></h1><blockquote><p><strong>一句话定位</strong>：IIoT 干三件事——<strong>采得上、存得住、用得了</strong>。90% 的项目死在第一件。</p><p><strong>本文用途</strong>：协议、点表、采集、存储、断线、告警六条主线上的核心问题与解法。配套：<a href="/my-vitepress-site/scenarios/enterprise-digital/erp.html">ERP</a> · <a href="/my-vitepress-site/scenarios/enterprise-digital/wms.html">WMS</a> · <a href="/my-vitepress-site/scenarios/enterprise-digital/mes.html">MES</a>。</p></blockquote><h2 id="一、iiot-在做什么" tabindex="-1">一、IIoT 在做什么 <a class="header-anchor" href="#一、iiot-在做什么" aria-label="Permalink to “一、IIoT 在做什么”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设备（PLC / 仪表 / 机床 / 机器人）</span></span>
<span class="line"><span>   │  协议：Modbus / S7 / OPC UA / 私有协议</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>边缘网关（采集、解析、缓存、规则判断）</span></span>
<span class="line"><span>   │  MQTT / HTTP / Kafka</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>平台（接入、时序存储、告警、规则、API）</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>消费方：MES（设备状态/产量）、看板、BI、预测性维护</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p><strong>关键认知</strong>：IIoT 不是&quot;读个数据存起来&quot;。它是<strong>工业现场与 IT 系统之间的翻译层 + 缓冲层 + 兜底层</strong>。现场的协议脏、网络差、时钟乱，这些都要在这一层消化掉，不能漏给上层。</p><h2 id="二、核心问题清单" tabindex="-1">二、核心问题清单 <a class="header-anchor" href="#二、核心问题清单" aria-label="Permalink to “二、核心问题清单”">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>核心问题</th><th>为什么难</th><th>典型后果</th></tr></thead><tbody><tr><td>1</td><td><strong>协议碎片化</strong></td><td>Modbus/S7/OPC UA/私有，每家都不一样</td><td>接一台设备写一套代码</td></tr><tr><td>2</td><td><strong>点表管理</strong></td><td>上万点位、地址/类型/字节序/缩放</td><td>配错一个位，数据全错</td></tr><tr><td>3</td><td><strong>采集频率与数据量</strong></td><td>毫秒级 vs 分钟级，写放大</td><td>存储爆炸，查询卡死</td></tr><tr><td>4</td><td><strong>网络不稳断线</strong></td><td>车间网、无线、4G 都会断</td><td>数据缺口，事后查不到</td></tr><tr><td>5</td><td><strong>数据质量</strong></td><td>空值、0 值、跳变、时钟漂移</td><td>报表全是脏数据</td></tr><tr><td>6</td><td><strong>边缘与云协同</strong></td><td>规则下发、断网自治、OTA</td><td>断网就停产</td></tr><tr><td>7</td><td><strong>指令下行安全</strong></td><td>写 PLC 有物理风险</td><td>误操作停机或损坏设备</td></tr><tr><td>8</td><td><strong>海量连接</strong></td><td>几千设备长连接、心跳、会话</td><td>网关内存爆、连接掉</td></tr><tr><td>9</td><td><strong>告警风暴</strong></td><td>抖动、级联、重复</td><td>报警没人看，等于没有</td></tr><tr><td>10</td><td><strong>工控安全</strong></td><td>生产网不能直接连外网</td><td>要么不通，要么裸奔</td></tr></tbody></table><h2 id="三、五个深水区逐个拆" tabindex="-1">三、五个深水区逐个拆 <a class="header-anchor" href="#三、五个深水区逐个拆" aria-label="Permalink to “三、五个深水区逐个拆”">​</a></h2><h3 id="_1-协议选型-先看设备-再看场景" tabindex="-1">1. 协议选型：先看设备，再看场景 <a class="header-anchor" href="#_1-协议选型-先看设备-再看场景" aria-label="Permalink to “1. 协议选型：先看设备，再看场景”">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>传输</th><th>特点</th><th>适用</th></tr></thead><tbody><tr><td><strong>Modbus RTU</strong></td><td>RS485 串口</td><td>简单、便宜、主从轮询</td><td>老设备、仪表、电表</td></tr><tr><td><strong>Modbus TCP</strong></td><td>以太网</td><td>同上，走 TCP 502</td><td>支持网口的 PLC、仪表</td></tr><tr><td><strong>S7（西门子）</strong></td><td>以太网</td><td>西门子私有，需按 DB 块地址读</td><td>西门子 S7-200/300/1200/1500</td></tr><tr><td><strong>OPC UA</strong></td><td>TCP/HTTPS</td><td>标准、自带信息模型、有安全机制</td><td>新设备、跨厂商集成</td></tr><tr><td><strong>MQTT</strong></td><td>TCP</td><td>轻量、发布订阅、QoS 可选</td><td>设备→平台的上行通道</td></tr><tr><td><strong>Profinet / EtherCAT</strong></td><td>实时以太网</td><td>硬实时，微秒级</td><td>产线控制层，一般不由 IT 直采</td></tr></tbody></table><p><strong>选型判断顺序</strong>：</p><ol><li>设备自带什么口？（网口优先，串口兜底）</li><li>厂家开放什么协议？（先查手册，别自己猜寄存器）</li><li>数据要什么实时性？（控制级 vs 监控级，差一个数量级）</li><li>一台网关带多少点？（RTU 轮询受波特率限制，点多必须拆）</li></ol><p><strong>踩坑提醒</strong>：Modbus 串口一条总线挂太多从站，轮询一轮就要几秒——这不是软件问题，是物理限制。点位多就多条总线、多个网关。</p><h3 id="_2-点表管理-配错一个位-全场数据作废" tabindex="-1">2. 点表管理：配错一个位，全场数据作废 <a class="header-anchor" href="#_2-点表管理-配错一个位-全场数据作废" aria-label="Permalink to “2. 点表管理：配错一个位，全场数据作废”">​</a></h3><p><strong>点表要描述的东西</strong>：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>设备 → 点位（tag）</span></span>
<span class="line"><span>  ├── 地址：40001（Modbus 保持寄存器）、DB1.DBD0（S7）</span></span>
<span class="line"><span>  ├── 数据类型：bool / int16 / uint16 / int32 / float32</span></span>
<span class="line"><span>  ├── 字节序：ABCD / CDAB / BADC / DCBA   ← 32 位最易错</span></span>
<span class="line"><span>  ├── 缩放：raw × 0.1 → 实际值（温度、压力）</span></span>
<span class="line"><span>  ├── 单位与量程：℃，0~150</span></span>
<span class="line"><span>  ├── 采集周期：1000ms</span></span>
<span class="line"><span>  └── 死区（deadband）：变化超过阈值才上报</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>字节序为什么是重灾区</strong>：Modbus 寄存器是 16 位，一个 32 位浮点要占两个寄存器。四个字节怎么排，不同厂家完全不同：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ABCD（大端）  CDAB（字交换，最常见）  BADC  DCBA（小端）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>表现就是&quot;读出来是 1.2e-38 这种乱数&quot;。<strong>处理办法</strong>：点表里显式配 <code>byte_order</code>，采集层统一转成 Java 的 <code>float</code>，绝对不在业务层做转换。</p><p><strong>点表必须配置化，不能硬编码</strong>：</p><div class="language-sql line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">iot_point(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  id, device_id, tag_code, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, data_type, byte_order,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  scale, offset, unit, min_val, max_val,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  collect_interval, deadband, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">enabled</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>改点表不用改代码、不用重启采集进程——这是能否交付 100 台设备的分水岭。</p><blockquote><p><strong>面试口径</strong>：IIoT 项目里最耗时的不是写协议，是核对点表。我的做法是把点表做成配置表 + 校验工具：配完先在网关上模拟读一遍，把原始值和换算值并排显示给现场工程师确认，确认后再启用。硬编码点表的项目，第二个车间就要重写。</p></blockquote><h3 id="_3-采集分层与存储-别把秒级数据当毫秒级存" tabindex="-1">3. 采集分层与存储：别把秒级数据当毫秒级存 <a class="header-anchor" href="#_3-采集分层与存储-别把秒级数据当毫秒级存" aria-label="Permalink to “3. 采集分层与存储：别把秒级数据当毫秒级存”">​</a></h3><p><strong>分层原则</strong>：</p><table tabindex="0"><thead><tr><th>层级</th><th>频率</th><th>用途</th><th>存哪</th><th>保留</th></tr></thead><tbody><tr><td>实时值</td><td>秒级</td><td>看板、当前状态</td><td>Redis / 内存</td><td>只留最新</td></tr><tr><td>明细</td><td>秒~分钟</td><td>趋势、追溯</td><td>时序库</td><td>3~12 个月</td></tr><tr><td>聚合</td><td>分钟~小时</td><td>报表、OEE</td><td>关系库</td><td>长期</td></tr><tr><td>事件</td><td>触发式</td><td>报警、停机</td><td>关系库</td><td>长期</td></tr></tbody></table><p><strong>写放大的来源</strong>：1000 个点位 × 1 秒 = 8.6 万点/秒。如果每条一个 INSERT，数据库直接被打死。</p><p><strong>三个优化手段</strong>：</p><ol><li><strong>批量写</strong>：边缘侧攒 500~2000 条一批，或者按 200ms 窗口批量提交。</li><li><strong>死区过滤</strong>：值没变就不上报（<code>ABS(new - last) &gt; deadband</code>），实际数据量常能降 70% 以上。</li><li><strong>列式/时序存储</strong>：按设备 + 时间戳建索引，压缩编码（delta-of-delta + 字典编码）。</li></ol><p><strong>时序库选型</strong>：</p><table tabindex="0"><thead><tr><th>方案</th><th>优势</th><th>短板</th><th>适合</th></tr></thead><tbody><tr><td><strong>TDengine</strong></td><td>国产、压缩比高、SQL 友好、超级表模型贴合设备场景</td><td>生态相对小</td><td>设备数量多、写入量大</td></tr><tr><td><strong>InfluxDB</strong></td><td>生态好、查询语言成熟</td><td>集群版收费，版本差异大</td><td>中小规模、快速起步</td></tr><tr><td><strong>TimescaleDB</strong></td><td>PG 扩展，SQL 能力完整，可 JOIN 业务表</td><td>超大数据量需调优</td><td>已有 PG 技术栈</td></tr><tr><td><strong>ClickHouse</strong></td><td>分析查询极快</td><td>不适合单点更新/高频小写入</td><td>事后分析、大屏聚合</td></tr></tbody></table><blockquote><p><strong>面试口径</strong>：选时序库先算三个数——设备数 × 点位数 × 采集频率 = 每秒写入点；再算单点字节数 × 保留时长 = 存储量。算完这两个数，选型基本没悬念。我倾向 TDengine 或 TimescaleDB，前者省存储，后者省学习成本。</p></blockquote><h3 id="_4-断线不丢数-边缘缓冲-补传去重" tabindex="-1">4. 断线不丢数：边缘缓冲 + 补传去重 <a class="header-anchor" href="#_4-断线不丢数-边缘缓冲-补传去重" aria-label="Permalink to “4. 断线不丢数：边缘缓冲 + 补传去重”">​</a></h3><p><strong>问题</strong>：车间网络断 30 分钟，这 30 分钟的产量、温度曲线全没了。事后查质量事故，正好缺这一段。</p><p><strong>标准解法</strong>：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>边缘网关</span></span>
<span class="line"><span>  ├── 采集 → 本地环形缓冲（SQLite / RocksDB / 内存队列）</span></span>
<span class="line"><span>  ├── 网络正常 → 实时上报</span></span>
<span class="line"><span>  ├── 网络断 → 写本地，标记 seq（单调递增）</span></span>
<span class="line"><span>  └── 恢复 → 按 seq 补传，服务端幂等去重</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><strong>去重键</strong>：<code>(device_id, tag_code, ts)</code> 建唯一索引，重复插入忽略。</p><p><strong>时间戳必须由边缘生成</strong>，不能用平台接收时间——补传时数据是&quot;旧&quot;的，用接收时间会全部错位。</p><p><strong>边缘自治</strong>：断网时网关要能继续跑规则（本地告警、本地联锁），不能因为连不上云就罢工。这是&quot;边缘计算&quot;存在的真实理由。</p><blockquote><p><strong>面试口径</strong>：断线不丢数的关键有两处——一是边缘要能缓存足够长的数据（按最坏断网时长估算容量），二是补传必须幂等，因为补传过程本身也会超时重试。时间戳一定要在采集侧打，这是很多人踩过的坑。</p></blockquote><h3 id="_5-告警收敛-从-报警没人看-到-报警就是命令" tabindex="-1">5. 告警收敛：从&quot;报警没人看&quot;到&quot;报警就是命令&quot; <a class="header-anchor" href="#_5-告警收敛-从-报警没人看-到-报警就是命令" aria-label="Permalink to “5. 告警收敛：从&quot;报警没人看&quot;到&quot;报警就是命令&quot;”">​</a></h3><p><strong>告警风暴的三种成因</strong>：</p><table tabindex="0"><thead><tr><th>成因</th><th>表现</th><th>解法</th></tr></thead><tbody><tr><td>抖动</td><td>温度在阈值附近反复进出，一天 200 条</td><td>连续 N 次超阈值才触发 + 静默期</td></tr><tr><td>级联</td><td>一个网关掉线，底下 500 个点位全报</td><td>拓扑抑制：父节点告警时抑制子节点</td></tr><tr><td>重复</td><td>同设备同指标多渠道重复推</td><td>去重键 <code>(device, metric, 窗口)</code> 合并</td></tr></tbody></table><p><strong>分级</strong>：P0 停机/安全 → 电话+短信；P1 影响产能 → 企微/钉钉；P2 需关注 → 站内信日报。</p><p><strong>状态机</strong>：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NORMAL → FIRING（触发）→ ACKNOWLEDGED（已确认）→ RESOLVED（恢复）</span></span>
<span class="line"><span>                              ↓</span></span>
<span class="line"><span>                         升级（超时未确认 → 通知上级）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>必须有&quot;已确认&quot;这一环，否则值班的人只能看着，不能表态。</p><blockquote><p><strong>面试口径</strong>：告警系统的核心指标不是&quot;数量&quot;，是&quot;有效告警率&quot;和&quot;平均响应时间&quot;。做完之后要去统计有多少告警被人为忽略，被忽略的那部分就是噪声，要么改阈值要么抑制。</p></blockquote><h2 id="四、面试高频追问" tabindex="-1">四、面试高频追问 <a class="header-anchor" href="#四、面试高频追问" aria-label="Permalink to “四、面试高频追问”">​</a></h2><p><strong>Q1：几千台设备的长连接怎么撑？</strong> A：Netty 做接入层，<code>boss/worker</code> 线程数按核数配；设备会话放 Redis（<code>device:{id} → node</code>），节点无状态可水平扩；心跳用 MQTT 的 keepalive 或自定义 ping/pong，超时 2.5 倍时间判定离线；离线事件走延迟队列，不要靠定时扫全表。</p><p><strong>Q2：MQTT 的 QoS 怎么选？</strong> A：QoS 0 最多一次（丢了不管，适合高频非关键）；QoS 1 至少一次（可能重复，业务侧要做幂等，最常用）；QoS 2 恰好一次（握手多、开销大，关键指令才用）。绝大多数遥测数据用 QoS 1 + 服务端幂等就够了。</p><p><strong>Q3：设备时间不准怎么办？</strong> A：三件事——采集侧尽量用统一授时（NTP / 网关对时）；时间戳以边缘采集时刻为准；平台侧做时钟偏移检测（和服务器时间差超过阈值就告警并记录偏移量），必要时按偏移量校正。</p><p><strong>Q4：一个点位读出来是乱数，怎么排查？</strong> A：按顺序——① 地址对不对（Modbus 的 40001 是&quot;第 1 个保持寄存器&quot;，但报文里从站地址要减 1）；② 数据类型对不对（把 float 当 int32 读）；③ 字节序对不对（CDAB 最常见）；④ 缩放因子是否漏乘。工具上先用 Modbus Poll 之类的现成工具验证，确认能读到正确值再写代码。</p><p><strong>Q5：IIoT 和 SCADA 什么关系？</strong> A：SCADA 偏控制与监控（实时性强、闭环），IIoT 偏数据汇聚与分析（跨系统、上云）。技术上 IIoT 常从 SCADA 或 OPC UA 服务器取数据，不直接碰底层 PLC，这样既安全又不干扰控制。</p><p><strong>Q6：怎么保证不下行错指令？</strong> A：三道闸——① 网络隔离，生产网与办公网单向或经 DMZ；② 指令白名单，只允许预定义的指令模板，不允许任意寄存器写入；③ 二次确认 + 超时回读校验，写完读回值比对，不一致立即告警。写 PLC 是物理世界操作，必须当成高风险动作设计。</p><h2 id="五、30-秒速答卡" tabindex="-1">五、30 秒速答卡 <a class="header-anchor" href="#五、30-秒速答卡" aria-label="Permalink to “五、30 秒速答卡”">​</a></h2><blockquote><p>IIoT 我理解是三个&quot;翻译&quot;：协议翻译（Modbus/S7/OPC UA 到统一模型）、时间翻译（边缘打时间戳、批量对齐）、语义翻译（原始值到带单位的工程量）。技术上最关键的四个点：点表必须配置化并显式配字节序，不然每家设备都要改代码；采集要分层，秒级实时值进 Redis、明细进时序库、聚合进关系库，配合死区过滤和批量写控制写放大；断网必须边缘缓存加补传幂等，时间戳在采集侧生成；告警要做抖动过滤、级联抑制和确认升级，否则报警等于没有。</p></blockquote><hr><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to “关联”">​</a></h2><ul><li><a href="/my-vitepress-site/scenarios/enterprise-digital/">四大系统边界与问题全景</a></li><li><a href="/my-vitepress-site/scenarios/enterprise-digital/mes.html">MES 核心问题清单</a>（设备状态与 OEE 的上游）</li><li>实例：<a href="/my-vitepress-site/apps/industrial/plc-collect.html">PLC 数据采集方案</a> · <a href="/my-vitepress-site/apps/industrial/protocol-bridge.html">Modbus/S7 协议对接实践</a> · <a href="/my-vitepress-site/apps/industrial/device-monitor.html">设备监控与告警</a> · <a href="/my-vitepress-site/apps/industrial/iot-platform.html">物联网数据平台搭建</a></li><li>架构：<a href="/my-vitepress-site/apps/industrial/enterprise-architecture.html">大型制造企业架构设计</a></li></ul><p>上一级：<a href="/my-vitepress-site/scenarios/enterprise-digital/">企业数字化</a></p>`,61)])])}const g=s(r,[["render",i]]);export{b as __pageData,g as default};
